import{_ as e,o as s,c as n,a2 as t}from"./chunks/framework.EUByU7Iq.js";const _=JSON.parse('{"title":"第八章　附　　则","description":"","frontmatter":{"title":"第八章　附　　则","date":"2021-08-21T00:00:00.000Z","categories":["法律","个人信息保护法"],"tags":["法律","个人信息保护法"]},"headers":[],"relativePath":"blogs/PIPL/dibazhang：fuze.md","filePath":"blogs/PIPL/第八章：附则.md"}'),p={name:"blogs/PIPL/dibazhang：fuze.md"};function i(l,a,r,o,c,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h3 id="第七十二条" tabindex="-1">第七十二条 <a class="header-anchor" href="#第七十二条" aria-label="Permalink to &quot;第七十二条&quot;">​</a></h3><p>自然人因个人或者家庭事务处理个人信息的，不适用本法。</p><p>法律对各级人民政府及其有关部门组织实施的统计、档案管理活动中的个人信息处理有规定的，适用其规定。</p><h3 id="第七十三条" tabindex="-1">第七十三条 <a class="header-anchor" href="#第七十三条" aria-label="Permalink to &quot;第七十三条&quot;">​</a></h3><p>本法下列用语的含义：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>（一）个人信息处理者，是指在个人信息处理活动中自主决定处理目的、处理方式的组织、个人。</span></span>
<span class="line"><span>（二）自动化决策，是指通过计算机程序自动分析、评估个人的行为习惯、兴趣爱好或者经济、健康、信用状况等，并进行决策的活动。</span></span>
<span class="line"><span>（三）去标识化，是指个人信息经过处理，使其在不借助额外信息的情况下无法识别特定自然人的过程。</span></span>
<span class="line"><span>（四）匿名化，是指个人信息经过处理无法识别特定自然人且不能复原的过程。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="第七十四条" tabindex="-1">第七十四条 <a class="header-anchor" href="#第七十四条" aria-label="Permalink to &quot;第七十四条&quot;">​</a></h3><p>本法自2021年11月1日起施行。</p>`,8)])])}const b=e(p,[["render",i]]);export{_ as __pageData,b as default};
